mkdir "$HOME/jvm-diag-lab" && cat > "$HOME/jvm-diag-lab/ProbaJVM.java" <<'JAVA'
public class ProbaJVM {
    static final byte[] DANE = new byte[2*1024*1024];
    public static void main(String[] args) throws Exception {
        Thread watek = new Thread(() -> {
            try { Thread.sleep(600000); }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }, "proba-oczekiwanie");
        watek.start();
        Thread.sleep(600000);
    }
}
